mcp:tool-listener.mcp:parameters-schema:
{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"referencia": {
			"type": "string",
			"description": "Referencia del pago: el localizador de la reserva"
		},
		"importe": {
			"type": "number",
			"exclusiveMinimum": 0,
			"description": "Importe total en euros"
		},
		"concepto": {
			"type": "string",
			"description": "Concepto que verá el cliente en la página de pago"
		},
		"correlationId": {
			"type": "string",
			"description": "Identificador de trazabilidad de la petición. Opcional: si la solicitud trae un correlationId, cópialo tal cual"
		}
	},
	"required": [
		"referencia",
		"importe"
	]
}

{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"idPago": {
			"type": "string",
			"description": "Identificador del pago devuelto por crear_pago (p. ej. SP-1A2B3C4D5E)"
		},
		"correlationId": {
			"type": "string",
			"description": "Identificador de trazabilidad de la petición. Opcional: si la solicitud trae un correlationId, cópialo tal cual"
		}
	},
	"required": [
		"idPago"
	]
}
